package platform
import("errors";"fmt";"testing";"time";"golang.org/x/sys/windows";"golang.org/x/sys/windows/registry")
func fixtureStartup(t *testing.T) registry.Key {
 t.Helper();old:=startupRegistryPath;startupRegistryPath=fmt.Sprintf(`Software\SteamSageTests\%d`,time.Now().UnixNano())
 key,_,err:=registry.CreateKey(registry.CURRENT_USER,startupRegistryPath,registry.ALL_ACCESS);if err!=nil{t.Fatal(err)}
 path:=startupRegistryPath;t.Cleanup(func(){key.Close();registry.DeleteKey(registry.CURRENT_USER,path);startupRegistryPath=old});return key
}
const fixtureEXE=`C:\Users\用户 name\Steam Sage\steam-sage-companion.exe`
const fixtureConfig=`C:\Users\用户 name\AppData\Roaming\steam-sage-companion`
const fixtureCommand=`"C:\Users\用户 name\Steam Sage\steam-sage-companion.exe" serve --background --config-dir "C:\Users\用户 name\AppData\Roaming\steam-sage-companion"`
func startupValue(t *testing.T,key registry.Key)string{t.Helper();s,_,err:=key.GetStringValue("SteamSageCompanion");if err==registry.ErrNotExist{return ""};if err!=nil{t.Fatal(err)};return s}
func TestWindowsStartupOwnEnableAndRemove(t *testing.T){key:=fixtureStartup(t);if err:=SetStartup(false,fixtureEXE,fixtureConfig);err!=nil{t.Fatal(err)};if got:=startupValue(t,key);got!=""{t.Fatal("default enabled startup")};if err:=SetStartup(true,fixtureEXE,fixtureConfig);err!=nil{t.Fatal(err)};got:=startupValue(t,key);if got!=fixtureCommand{t.Fatalf("command=%q",got)};argv,err:=windows.DecomposeCommandLine(got);if err!=nil || len(argv)!=5 || argv[0]!=fixtureEXE || argv[4]!=fixtureConfig{t.Fatalf("invalid native argument quoting: %q %v",argv,err)};if err:=SetStartup(false,fixtureEXE,fixtureConfig);err!=nil{t.Fatal(err)};if got:=startupValue(t,key);got!=""{t.Fatal("owned startup retained")}}
func TestWindowsStartupPreservesForeignValues(t *testing.T){for _,enabled:=range []bool{true,false}{t.Run(fmt.Sprint(enabled),func(t *testing.T){key:=fixtureStartup(t);foreign:=`C:\Other\foreign.exe --flag`;if err:=key.SetStringValue("SteamSageCompanion",foreign);err!=nil{t.Fatal(err)};if err:=SetStartup(enabled,fixtureEXE,fixtureConfig);err==nil{t.Fatal("accepted foreign startup registration")};if got:=startupValue(t,key);got!=foreign{t.Fatalf("foreign registration changed: %q",got)}})}}
func TestWindowsStartupTransactionRollback(t *testing.T){for _,enabled:=range []bool{true,false}{t.Run(fmt.Sprint(enabled),func(t *testing.T){key:=fixtureStartup(t);before:="";if !enabled{before=fixtureCommand;if err:=key.SetStringValue("SteamSageCompanion",before);err!=nil{t.Fatal(err)}};sentinel:=errors.New("settings persistence failed");called:=false;err:=SetStartupTransaction(enabled,fixtureEXE,fixtureConfig,func()error{called=true;want:="";if enabled{want=fixtureCommand};if got:=startupValue(t,key);got!=want{t.Fatalf("persist sees wrong startup state: %q",got)};return sentinel});if !called || !errors.Is(err,sentinel){t.Fatalf("persist error lost: called=%v err=%v",called,err)};if got:=startupValue(t,key);got!=before{t.Fatalf("rollback lost prior registration: %q",got)}})}}
func TestWindowsStartupRollbackPreservesConcurrentChange(t *testing.T){key:=fixtureStartup(t);foreign:=`C:\Changed\other.exe`;sentinel:=errors.New("save failed");err:=SetStartupTransaction(true,fixtureEXE,fixtureConfig,func()error{if err:=key.SetStringValue("SteamSageCompanion",foreign);err!=nil{t.Fatal(err)};return sentinel});if !errors.Is(err,sentinel){t.Fatalf("persist error lost: %v",err)};if got:=startupValue(t,key);got!=foreign{t.Fatalf("rollback erased concurrent change: %q",got)}}
